#include <vector>
#include <string>
#include <cstddef>
#include <omp.h>

struct Book {
    std::string title;
    int pages;
};

/* Return the index of the last Book item in the vector books where Book.pages is less than 100.
   If no such book exists, returns books.size().
*/
size_t findLastShortBook(std::vector<Book> const& books) {
    const size_t n = books.size();
    size_t lastIndex = n; // Sentinel for "not found"

    #pragma omp parallel
    {
        size_t localLast = n;

        #pragma omp for nowait
        for (size_t i = 0; i < n; ++i) {
            if (books[i].pages < 100) {
                if (localLast == n || i > localLast) {
                    localLast = i;
                }
            }
        }

        #pragma omp critical
        {
            if (localLast != n && (lastIndex == n || localLast > lastIndex)) {
                lastIndex = localLast;
            }
        }
    }

    return lastIndex;
}
